// 一个最朴素的对象生命周期观察
public class LifeCycle {
    public static void main(String[] args) {
        Object o = new Object();   // 分配：对象进入 Eden 区，变量 o 指向它
        o = null;                  // 断开：栈帧里的 o 不再指向原对象
        // 此刻原对象已不可达，但内存并未立刻归还
        System.gc();               // 只是建议，不是命令，回收器可以完全无视
    }
}

// 循环引用：引用计数永远归零不了，可达性分析却能正确判定为垃圾
class Node {
    Node next;
}
Node a = new Node();
Node b = new Node();
a.next = b;   // a 计数 1
b.next = a;   // b 计数 1
// 把外部引用全部断开后，a 与 b 仍然互相指着
// 引用计数：两个都是 1，永远不回收，泄漏
a = null;
b = null;
// 可达性分析：从 GC Roots 出发走不到 a 与 b，判定为垃圾，正确回收

// 四种引用强度从强到弱
