WeakReference<Object> weak = new WeakReference<>(new Object());             // 弱引用：每次 GC 都清
ReferenceQueue<Object> queue = new ReferenceQueue<>();
PhantomReference<Object> phantom = new PhantomReference<>(new Object(), queue);  // 虚引用：回收通知
// 取回对象：soft.get() 可能为 null，必须判空
