// 同一个对象，放在不同位置，生命周期完全不同
public class RootDemo {
    static final Map<String, byte[]> CACHE = new HashMap<>();   // 静态字段：永久根
    static final ThreadLocal<byte[]> LOCAL = new ThreadLocal<>();

    void leak() {
        byte[] big = new byte[10 * 1024 * 1024];  // 局部变量：方法返回后不再是根
        CACHE.put("big", big);                    // 变成静态字段可达，永不回收
        LOCAL.set(big);                           // 挂在线程上，线程活多久它就活多久
    }
}

// 模拟一次初始标记的停顿：线程越多，枚举越慢
public class PauseProbe {
    public static void main(String[] args) throws Exception {
        for (int i = 0; i < 2000; i++) {          // 2000 个线程
            Thread t = new Thread(() -> {
                Object hold = new Object();        // 每个线程栈上都持有引用
                try { Thread.sleep(600000); } catch (InterruptedException e) { }
                System.out.println(hold);          // 保证 hold 不被优化掉
            });
            t.setDaemon(true);
            t.start();
        }
        System.out.println("线程就绪，观察 GC 日志里的初始标记停顿");
        System.gc();
    }
}

// 长循环曾经拖慢安全点：JDK 10 前 counted loop 内部不插检查点
public class LongLoop {
    public static void main(String[] args) {
        long sum = 0;
        for (int i = 0; i < 2_000_000_000; i++) {   // 可数循环，边界明确
            sum += i;                                // 循环体内没有任何方法调用
        }
        System.out.println(sum);
    }
}

// 阻塞线程处于安全区域，GC 不必等它们
public class SafeRegionDemo {
    public static void main(String[] args) {
        Object keep = new Object();                 // 主线程持有引用
        Thread blocked = new Thread(() -> {
            try {
                Thread.sleep(60_000);               // 进入阻塞，标记为在安全区域
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        blocked.start();
        System.out.println(keep);
        System.gc();                                // 不必等 blocked 到达安全点
    }
}

