// 三色标记的伪代码：这段逻辑就是标记线程干的事
void markFromRoots() {
    grayStack.pushAll(gcRoots);            // 根直接引用涂灰，入栈
    while (!grayStack.isEmpty()) {
        Object obj = grayStack.pop();      // 取一个灰对象
        for (Object ref : obj.references()) {  // 扫描它的每个字段
            if (isWhite(ref)) {            // 白对象才有必要处理
                markGray(ref);             // 涂灰
                grayStack.push(ref);       // 加入待办
            }
        }
        markBlack(obj);                    // 自己处理完了，涂黑
    }
}

// 两种写屏障的伪代码差异，注意记录的内容不同
// 增量更新：记录被写入的新引用（破坏条件一）
void writeBarrierIncremental(Object obj, Object newRef) {
    if (isBlack(obj) && isWhite(newRef)) {
        updateBuffer.push(newRef);       // 记下来，最终标记时重扫
    }
    obj.field = newRef;
}

// SATB：记录被删除的旧引用（破坏条件二）
void writeBarrierSatb(Object obj, Object oldRef) {
    if (oldRef != null) {
        satbBuffer.push(oldRef);         // 旧值当作快照存活，记下来
    }
    obj.field = newValue;
}

